<?php

namespace App\Support;

use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Http;
use Throwable;

class LotteFinanceSchemeCatalog
{
    public static function options(): array
    {
        return collect(self::details())
            ->mapWithKeys(fn (array $scheme, string $code): array => [$code => self::label($scheme, $code)])
            ->sortKeys()
            ->all();
    }

    public static function topOptions(int $limit = 150): array
    {
        $live = self::fetchSchemeList('', 0, $limit);

        if ($live !== []) {
            return self::optionMap($live);
        }

        return array_slice(self::options(), 0, $limit, true);
    }

    public static function searchOptions(string $search, int $limit = 150): array
    {
        $search = trim($search);
        $live = self::fetchSchemeList($search, 0, $limit);

        if ($live !== []) {
            return self::optionMap($live);
        }

        $needle = mb_strtolower($search);

        if ($needle === '') {
            return self::topOptions($limit);
        }

        return collect(self::options())
            ->filter(fn (string $label, string $code): bool => str_contains(mb_strtolower($code.' '.$label), $needle))
            ->take($limit)
            ->all();
    }

    public static function optionLabel(?string $code): ?string
    {
        if (blank($code)) {
            return null;
        }

        $scheme = self::find($code);

        return $scheme === [] ? $code : self::label($scheme, $code);
    }

    public static function find(?string $code): array
    {
        if (blank($code)) {
            return [];
        }

        $code = strtoupper(trim((string) $code));
        $fallback = self::staticDetails()[$code] ?? (self::apiDetails()[$code] ?? []);
        $liveDetail = self::fetchSchemeDetail($code, $fallback['sid'] ?? null);

        if ($liveDetail !== []) {
            return array_replace($fallback, $liveDetail);
        }

        return $fallback;
    }

    public static function label(array $scheme, ?string $code = null): string
    {
        $prefix = $code ?: ($scheme['scheme_code'] ?? '');

        if (($scheme['source'] ?? null) === 'product_config_map') {
            return trim($scheme['label'] ?? $prefix);
        }

        $name = $scheme['name'] ?? ($scheme['label'] ?? $prefix);
        $name = preg_replace('/^'.preg_quote($prefix, '/').'\s*-?\s*/i', '', $name) ?: $name;

        return trim($prefix.($name === '' || $name === $prefix ? '' : ' - '.$name));
    }

    public static function loanPurposeOptions(): array
    {
        return [
            'Purchase home appliances or other product' => 'Mua đồ dùng cá nhân, gia đình',
            'Purchase vehicles, devices' => 'Mua, thuê, thuê mua phương tiện đi lại',
            'Education, travel, beauty, sport or other services' => 'Học tập/chữa bệnh/Du lịch/Văn hóa/TDTT',
            'Home renovation' => 'Sửa chữa nhà ở',
        ];
    }

    public static function loanPurposeLabel(?string $code): ?string
    {
        if (blank($code)) {
            return null;
        }

        return self::loanPurposeOptions()[$code] ?? $code;
    }

    public static function insuranceOptions(): array
    {
        return [
            'INSUR69' => 'BHSK người vay: 6.9 %',
            'INSU1M' => 'Bảo hiểm 1M: 1000000 VNĐ',
            'INSU2M' => 'Bảo hiểm 2M: 2000000 VNĐ',
            'INSU3M' => 'Bảo hiểm 3M: 3000000 VNĐ',
        ];
    }

    public static function insuranceLabel(?string $code): ?string
    {
        if (blank($code)) {
            return null;
        }

        return self::insuranceOptions()[$code] ?? $code;
    }

    public static function insuranceAmount(float $principal, ?string $code): float
    {
        return match ($code) {
            'INSUR69' => round($principal * 0.069),
            'INSU1M' => 1000000,
            'INSU2M' => 2000000,
            'INSU3M' => 3000000,
            default => 0,
        };
    }

    public static function interestOptions(?string $schemeCode): array
    {
        $scheme = self::find($schemeCode);
        $interestOptions = $scheme['interest_options'] ?? [];

        if ($interestOptions !== []) {
            return collect($interestOptions)
                ->mapWithKeys(fn (array $interest): array => [$interest['label'] => $interest['label']])
                ->all();
        }

        $label = $scheme['interest_label'] ?? null;

        return filled($label) ? [$label => $label] : [];
    }

    public static function interestHelper(?string $schemeCode): ?string
    {
        $scheme = self::find($schemeCode);
        $interestOptions = $scheme['interest_options'] ?? [];

        if (count($interestOptions) > 1) {
            return 'Có '.count($interestOptions).' mức lãi suất theo kỳ hạn.';
        }

        $period = $scheme['interest_period'] ?? null;

        return filled($period) ? 'Áp dụng cho '.$period.' tháng đầu tiên' : null;
    }

    public static function details(): array
    {
        return array_replace(self::staticDetails(), self::apiDetails());
    }

    private static function staticDetails(): array
    {
        return array_replace(self::mappedDetails(), self::schemeDetails());
    }

    private static function apiDetails(): array
    {
        if (! self::liveApiEnabled()) {
            return [];
        }

        $cacheKey = 'lotte_finance.scheme_catalog.v4';

        try {
            $cached = Cache::get($cacheKey);

            if (is_array($cached)) {
                return $cached;
            }

            $schemes = self::fetchAllSchemes();

            if ($schemes !== []) {
                Cache::put($cacheKey, $schemes, now()->addMinutes(self::cacheTtlMinutes()));
            }

            return $schemes;
        } catch (Throwable) {
            return [];
        }
    }

    private static function fetchAllSchemes(): array
    {
        $limit = 500;
        $skip = 0;
        $all = [];
        $total = null;

        for ($page = 0; $page < 100; $page++) {
            $pageData = self::fetchSchemeListPage('', $skip, $limit);
            $schemes = $pageData['schemes'];

            if ($schemes === []) {
                break;
            }

            $all = array_replace($all, $schemes);
            $total ??= $pageData['total'];
            $skip += $limit;

            if ($total !== null && $skip >= $total) {
                break;
            }

            if ($total === null && count($schemes) < $limit) {
                break;
            }
        }

        ksort($all);

        return $all;
    }

    private static function fetchSchemeList(string $search = '', int $skip = 0, int $limit = 80, bool $useCache = true): array
    {
        if (! self::liveApiEnabled()) {
            return [];
        }

        $cacheKey = 'lotte_finance.scheme_search.v4.'.md5($search.'|'.$skip.'|'.$limit);
        $loader = fn (): array => self::fetchSchemeListPage($search, $skip, $limit)['schemes'];

        if (! $useCache) {
            return $loader();
        }

        try {
            $cached = Cache::get($cacheKey);

            if (is_array($cached)) {
                return $cached;
            }

            $schemes = $loader();

            if ($schemes !== []) {
                Cache::put($cacheKey, $schemes, now()->addMinutes(self::cacheTtlMinutes()));
            }

            return $schemes;
        } catch (Throwable) {
            return $loader();
        }
    }

    private static function fetchSchemeListPage(string $search, int $skip, int $limit): array
    {
        $json = self::postTransaction([
            'DEVICEID' => self::deviceId(),
            'SERVICEID' => self::serviceId('scheme_search'),
            'CRITERIAS' => [],
            'SEARCH' => [
                'name' => $search,
                'code' => $search,
            ],
            'SKIP' => $skip,
            'LIMIT' => $limit,
        ]);

        $items = data_get($json, 'data.schemeList.data', []);

        if (! is_array($items)) {
            return ['schemes' => [], 'total' => self::extractTotal($json)];
        }

        $schemes = [];

        foreach ($items as $item) {
            $normalized = self::normalizeScheme($item, 'scheme_api');

            if (($normalized['scheme_code'] ?? '') !== '') {
                $schemes[$normalized['scheme_code']] = $normalized;
            }
        }

        return ['schemes' => $schemes, 'total' => self::extractTotal($json)];
    }

    private static function extractTotal(array $json): ?int
    {
        foreach (['data.schemeList.count', 'data.schemeList.total', 'data.schemeList.totalDocs', 'data.count', 'data.total', 'count', 'total'] as $path) {
            $value = data_get($json, $path);

            if (is_numeric($value)) {
                return (int) $value;
            }
        }

        return null;
    }

    private static function fetchSchemeDetail(string $code, ?string $sid = null): array
    {
        if (! self::liveApiEnabled()) {
            return [];
        }

        $code = strtoupper(trim($code));
        $cacheKey = 'lotte_finance.scheme_detail.v4.'.md5($code.'|'.$sid);

        try {
            $cached = Cache::get($cacheKey);

            if (is_array($cached)) {
                return $cached;
            }

            $schemeId = $sid;

            if (blank($schemeId)) {
                $matches = self::fetchSchemeList($code, 0, 1, false);
                $schemeId = reset($matches)['sid'] ?? null;
            }

            if (blank($schemeId)) {
                return [];
            }

            $json = self::postTransaction([
                'DEVICEID' => self::deviceId(),
                'SERVICEID' => self::serviceId('scheme_detail'),
                'SCHEMEID' => $schemeId,
            ]);

            $detail = data_get($json, 'data.data', []);
            $normalized = is_array($detail) ? self::normalizeScheme($detail, 'scheme_detail_api') : [];

            if ($normalized !== []) {
                Cache::put($cacheKey, $normalized, now()->addMinutes(self::cacheTtlMinutes()));
            }

            return $normalized;
        } catch (Throwable) {
            return [];
        }
    }

    private static function postTransaction(array $payload): array
    {
        try {
            $response = Http::timeout(15)
                ->acceptJson()
                ->asJson()
                ->withToken((string) config('lotte_finance.bearer_token'))
                ->withHeaders([
                    'Accept-Language' => config('lotte_finance.accept_language', 'vi'),
                    'Version' => config('lotte_finance.api_version', '2.0.18'),
                    'Cache-Control' => 'no-store',
                ])
                ->post((string) config('lotte_finance.endpoint'), $payload);

            if (! $response->successful()) {
                return [];
            }

            $json = $response->json() ?: [];

            if ((int) data_get($json, 'err') === 8013) {
                Cache::put('lotte_finance.api_unavailable', true, now()->addMinutes(10));
            }

            return $json;
        } catch (Throwable) {
            return [];
        }
    }

    private static function normalizeScheme(array $scheme, string $source): array
    {
        $code = strtoupper(trim((string) data_get($scheme, 'code', '')));

        if ($code === '') {
            return [];
        }

        $subProductName = trim((string) data_get($scheme, 'subProductInfo.name', ''));
        $subProductCode = trim((string) data_get($scheme, 'subProductInfo.code', ''));
        $categoryCode = trim((string) data_get($scheme, 'subProductInfo.categoryCode', ''));
        $productLine = implode(' / ', array_values(array_unique(array_filter([$subProductName, $subProductCode, $categoryCode]))));
        $interestOptions = self::normalizeInterests([
            data_get($scheme, 'interest'),
            data_get($scheme, 'interestInfo'),
            data_get($scheme, 'interestRate'),
            data_get($scheme, 'interestRates'),
            data_get($scheme, 'loanInterest'),
            data_get($scheme, 'loanInterestList'),
            data_get($scheme, 'rate'),
            data_get($scheme, 'rateInfo'),
        ]);
        $primaryInterest = $interestOptions[0] ?? [];
        $loanMin = data_get($scheme, 'loanPeriod.min');
        $loanMax = data_get($scheme, 'loanPeriod.max');
        $startDate = self::formatApiDate(data_get($scheme, 'campaignInfo.startDate') ?: data_get($scheme, 'activatedAt'));
        $businessName = data_get($scheme, 'businessECM.name') ?: data_get($scheme, 'businessInfo.name') ?: 'Consumer Loan';
        $description = data_get($scheme, 'desc') ?: ($productLine ? 'Dòng sản phẩm: '.$productLine : null);

        return [
            'scheme_code' => $code,
            'label' => self::buildLabel($code, (string) data_get($scheme, 'name', $code)),
            'name' => (string) data_get($scheme, 'name', $code),
            'product_type' => $businessName,
            'product' => self::productName($subProductName, (string) data_get($scheme, 'name', '')),
            'product_line' => $productLine,
            'description' => $description,
            'sid' => (string) data_get($scheme, 'sid', ''),
            'loan_period' => filled($loanMin) && filled($loanMax) ? $loanMin.'-'.$loanMax.' tháng' : '',
            'loan_period_min' => filled($loanMin) ? (string) $loanMin : '',
            'loan_period_max' => filled($loanMax) ? (string) $loanMax : '',
            'interest_rate' => (string) ($primaryInterest['value'] ?? ''),
            'interest_code' => (string) ($primaryInterest['code'] ?? ''),
            'interest_period' => (string) ($primaryInterest['period'] ?? ''),
            'interest_label' => (string) ($primaryInterest['label'] ?? ''),
            'interest_options' => $interestOptions,
            'dti' => filled(data_get($scheme, 'dti')) ? (string) data_get($scheme, 'dti') : '',
            'dti_label' => filled(data_get($scheme, 'dti')) ? '<= '.data_get($scheme, 'dti').'%' : '',
            'ltv' => filled(data_get($scheme, 'ltv')) ? (string) data_get($scheme, 'ltv') : '',
            'start_date' => $startDate,
            'loan_amount_min' => filled(data_get($scheme, 'loanAmount.min')) ? (string) data_get($scheme, 'loanAmount.min') : '',
            'loan_amount_max' => filled(data_get($scheme, 'loanAmount.max')) ? (string) data_get($scheme, 'loanAmount.max') : '',
            'age_min' => filled(data_get($scheme, 'age.min')) ? (string) data_get($scheme, 'age.min') : '',
            'age_max' => filled(data_get($scheme, 'age.max')) ? (string) data_get($scheme, 'age.max') : '',
            'insurance_fee' => filled(data_get($scheme, 'insuranceFee')) ? (string) data_get($scheme, 'insuranceFee') : '',
            'source' => $source,
        ];
    }

    private static function normalizeInterests(mixed $interest): array
    {
        $items = [];
        $seen = [];

        $add = function (mixed $node, string $key = '') use (&$items, &$seen): void {
            if (! is_array($node)) {
                $node = ['value' => $node];
            }

            $rate = data_get($node, 'value')
                ?? data_get($node, 'rate')
                ?? data_get($node, 'interestRate')
                ?? data_get($node, 'percent')
                ?? data_get($node, 'percentage');

            if (! is_scalar($rate) || trim((string) $rate) === '') {
                return;
            }

            $rate = trim((string) $rate);
            $rate = rtrim($rate, '%');
            $code = trim((string) (data_get($node, 'code') ?? data_get($node, 'interestCode') ?? data_get($node, 'id') ?? ''));
            $period = trim((string) (data_get($node, 'period') ?? data_get($node, 'term') ?? data_get($node, 'months') ?? ''));
            $label = trim($rate.'%'.($code !== '' ? ' - '.$code : ''));

            if ($label === '%' || isset($seen[$label])) {
                return;
            }

            $seen[$label] = true;
            $items[] = [
                'key' => $key,
                'value' => $rate,
                'period' => $period,
                'type' => (string) (data_get($node, 'type') ?? ''),
                'code' => $code,
                'label' => $label,
            ];
        };

        $walk = function (mixed $node, string $key = '') use (&$walk, $add): void {
            if ($node === null || $node === '') {
                return;
            }

            if (! is_array($node)) {
                $add($node, $key);
                return;
            }

            if (data_get($node, 'value') !== null || data_get($node, 'rate') !== null || data_get($node, 'interestRate') !== null || data_get($node, 'percent') !== null || data_get($node, 'percentage') !== null) {
                $add($node, $key);
                return;
            }

            foreach ($node as $childKey => $child) {
                $walk($child, (string) $childKey);
            }
        };

        $walk($interest);

        return $items;
    }

    private static function optionMap(array $schemes): array
    {
        return collect($schemes)
            ->mapWithKeys(fn (array $scheme, string $code): array => [$code => self::label($scheme, $code)])
            ->all();
    }

    private static function buildLabel(string $code, string $name): string
    {
        $cleanName = preg_replace('/^'.preg_quote($code, '/').'\s*-?\s*/i', '', $name) ?: $name;

        return trim($code.($cleanName === '' || $cleanName === $code ? '' : ' - '.$cleanName));
    }

    private static function productName(string $subProductName, string $schemeName): string
    {
        if ($subProductName !== '') {
            return trim(explode('-', $subProductName)[0]);
        }

        if (preg_match('/-\s*([A-Z][A-Z0-9 ]+)/', $schemeName, $match)) {
            return trim(explode(' ', $match[1])[0]);
        }

        return '';
    }

    private static function formatApiDate(mixed $value): string
    {
        if (blank($value)) {
            return '';
        }

        try {
            return (new \DateTimeImmutable((string) $value))
                ->setTimezone(new \DateTimeZone(config('app.timezone', 'Asia/Ho_Chi_Minh')))
                ->format('d/m/Y');
        } catch (Throwable) {
            return (string) $value;
        }
    }

    private static function liveApiEnabled(): bool
    {
        return ! Cache::has('lotte_finance.api_unavailable')
            && (bool) config('lotte_finance.live_api_ready')
            && filled(config('lotte_finance.endpoint'))
            && filled(config('lotte_finance.bearer_token'))
            && filled(self::deviceId())
            && filled(self::serviceId('scheme_search'));
    }

    private static function deviceId(): string
    {
        return (string) config('lotte_finance.device_id');
    }

    private static function serviceId(string $key): ?string
    {
        return config("lotte_finance.steps.{$key}.service_id");
    }

    private static function cacheTtlMinutes(): int
    {
        return max(5, (int) config('lotte_finance.scheme_cache_ttl_minutes', 720));
    }

